ValidationRule.errorConditionFormula:
OR( /* Tier 1 incomplete */ AND( OR( NOT(ISBLANK(Tier_1_Minimum_Qty__c)), NOT(ISBLANK(Tier_1_Maximum_Qty__c)), NOT(ISBLANK(Tier_1_Unit_Price__c)) ), OR( ISBLANK(Tier_1_Minimum_Qty__c), ISBLANK(Tier_1_Maximum_Qty__c), ISBLANK(Tier_1_Unit_Price__c) ) ),
/* Tier 2 incomplete */ AND( OR( NOT(ISBLANK(Tier_2_Minimum_Qty__c)), NOT(ISBLANK(Tier_2_Maximum_Qty__c)), NOT(ISBLANK(Tier_2_Unit_Price__c)) ), OR( ISBLANK(Tier_2_Minimum_Qty__c), ISBLANK(Tier_2_Maximum_Qty__c), ISBLANK(Tier_2_Unit_Price__c) ) ),
/* Tier 3 incomplete */ AND( OR( NOT(ISBLANK(Tier_3_Minimum_Qty__c)), NOT(ISBLANK(Tier_3_Maximum_Qty__c)), NOT(ISBLANK(Tier_3_Unit_Price__c)) ), OR( ISBLANK(Tier_3_Minimum_Qty__c), ISBLANK(Tier_3_Maximum_Qty__c), ISBLANK(Tier_3_Unit_Price__c) ) ),
/* Tier 4 incomplete */ AND( OR( NOT(ISBLANK(Tier_4_Minimum_Qty__c)), NOT(ISBLANK(Tier_4_Maximum_Qty__c)), NOT(ISBLANK(Tier_4_Unit_Price__c)) ), OR( ISBLANK(Tier_4_Minimum_Qty__c), ISBLANK(Tier_4_Maximum_Qty__c), ISBLANK(Tier_4_Unit_Price__c) ) ),
/* Invalid ranges */ AND( NOT(ISBLANK(Tier_1_Minimum_Qty__c)), OR( Tier_1_Minimum_Qty__c <= 0, Tier_1_Minimum_Qty__c > Tier_1_Maximum_Qty__c ) ), AND( NOT(ISBLANK(Tier_2_Minimum_Qty__c)), OR( Tier_2_Minimum_Qty__c <= 0, Tier_2_Minimum_Qty__c > Tier_2_Maximum_Qty__c ) ), AND( NOT(ISBLANK(Tier_3_Minimum_Qty__c)), OR( Tier_3_Minimum_Qty__c <= 0, Tier_3_Minimum_Qty__c > Tier_3_Maximum_Qty__c ) ), AND( NOT(ISBLANK(Tier_4_Minimum_Qty__c)), OR( Tier_4_Minimum_Qty__c <= 0, Tier_4_Minimum_Qty__c > Tier_4_Maximum_Qty__c ) ),
/* Gaps or overlaps between configured tiers */ AND( NOT(ISBLANK(Tier_1_Minimum_Qty__c)), NOT(ISBLANK(Tier_2_Minimum_Qty__c)), Tier_2_Minimum_Qty__c <> Tier_1_Maximum_Qty__c + 1 ), AND( NOT(ISBLANK(Tier_1_Minimum_Qty__c)), ISBLANK(Tier_2_Minimum_Qty__c), NOT(ISBLANK(Tier_3_Minimum_Qty__c)), Tier_3_Minimum_Qty__c <> Tier_1_Maximum_Qty__c + 1 ), AND( NOT(ISBLANK(Tier_1_Minimum_Qty__c)), ISBLANK(Tier_2_Minimum_Qty__c), ISBLANK(Tier_3_Minimum_Qty__c), NOT(ISBLANK(Tier_4_Minimum_Qty__c)), Tier_4_Minimum_Qty__c <> Tier_1_Maximum_Qty__c + 1 ), AND( NOT(ISBLANK(Tier_2_Minimum_Qty__c)), NOT(ISBLANK(Tier_3_Minimum_Qty__c)), Tier_3_Minimum_Qty__c <> Tier_2_Maximum_Qty__c + 1 ), AND( NOT(ISBLANK(Tier_2_Minimum_Qty__c)), ISBLANK(Tier_3_Minimum_Qty__c), NOT(ISBLANK(Tier_4_Minimum_Qty__c)), Tier_4_Minimum_Qty__c <> Tier_2_Maximum_Qty__c + 1 ), AND( NOT(ISBLANK(Tier_3_Minimum_Qty__c)), NOT(ISBLANK(Tier_4_Minimum_Qty__c)), Tier_4_Minimum_Qty__c <> Tier_3_Maximum_Qty__c + 1 ) )
